local function set_list_values(t, start, ...)
    local values = pack_values(...)
    if table_create then
        local total = start + values.n - 1
        local replacement = table_create(total)
        for i = 1, total do replacement[i] = false end
        for k, v in next, t do replacement[k] = v end
        for i = 1, start - 1 do if t[i] == nil then replacement[i] = nil end end
        t = replacement
    end
