do
local function renderMovingParticle(upvalues, particle)
  math.random(0, 2147483646)
  local progress = particle.age / particle.life
  local lookAt = env.CFrame.lookAt
  local firstPosition = particle.pos
  local target = particle.pos - particle.dir
  local frame = lookAt(firstPosition, target)
  local angles = env.CFrame.Angles
  local sin = env.math.sin
  local x = sin(particle.age * 4 + particle.phase) * 0.35
  local z = particle.phase + particle.age * particle.spin
  local transform = frame * angles(x, 0, z)
  local render = cell_get(upvalues[1])
  local getSize = cell_get(upvalues[2])
  local age = particle.age
  local life = particle.life
  local maxSize = cell_get(upvalues[3])
  local size = getSize(age, life, maxSize)
  local transparency = 0.6 * progress ^ 4
  local fade = 0.85 * progress ^ 1.3
  render(particle, transform, size, transparency, fade)
end
protos[106] = renderMovingParticle
end

do
local function updateParticles107(upvalues, particles, deltaTime, update, render)
  math.random(0, 2147483646)
  local index = #particles
  while index >= 1 do
    local particle = particles[index]
    particle.age = particle.age + deltaTime
    if particle.age >= particle.life then
      local dispose = cell_get(upvalues[1])
      dispose(particle)
      local remove = env.table.remove
      remove(particles, index)
    else
      update(particle, deltaTime)
      render(particle)
    end
    index -= 1
  end
end
protos[107] = updateParticles107
end

